<template>
  <div class="po-body">
    <!-- 模型信息 -->
    <div class="po-sec">
      <div class="po-title">模型信息</div>
      <div class="po-kv"><span>模型名称</span><b>{{ info.label || '—' }}</b></div>
      <div class="po-kv"><span>模型文件</span><b>{{ info.file }}</b></div>
      <div class="po-kv"><span>总部件数</span><b>{{ info.totalParts }} 个</b></div>
      <div class="po-kv"><span>占地面积</span><b>{{ info.area ? info.area + ' m²' : '—' }}</b></div>
      <div class="po-kv"><span>内部净尺寸</span><b>{{ info.inner ? fmtInner(info.inner) : '—' }}</b></div>
      <div class="po-kv"><span>单位</span><b>米（外部净尺寸）</b></div>
    </div>

    <!-- 结构规格（用户给定设计值，仅展示元数据） -->
    <div v-if="info.specs && info.specs.length" class="po-sec">
      <div class="po-title">结构规格（设计值）</div>
      <div v-for="s in info.specs" :key="s.name" class="po-kv">
        <span>{{ s.name }}</span>
        <b>{{ s.mm }} mm（{{ (s.mm / 1000).toFixed(2) }} m）</b>
      </div>
    </div>

    <!-- 模型尺寸（可编辑） -->
    <div class="po-sec">
      <div class="po-title">模型尺寸（米）</div>
      <div class="po-size-row">
        <label><span>长 {{ axis.length.toUpperCase() }}</span><input ref="lenRef" type="number" step="0.01" min="0.01" v-model.number="draft[axis.length]" @change="applyModel"></label>
        <label><span>宽 {{ axis.width.toUpperCase() }}</span><input ref="widRef" type="number" step="0.01" min="0.01" v-model.number="draft[axis.width]" @change="applyModel"></label>
        <label><span>高 {{ axis.height.toUpperCase() }}</span><input ref="heiRef" type="number" step="0.01" min="0.01" v-model.number="draft[axis.height]" @change="applyModel"></label>
      </div>
      <div class="po-size-hint">修改后整体模型按新尺寸缩放（x/z 居中、底部贴地）</div>
    </div>

    <!-- 分组显隐 -->
    <div class="po-sec">
      <div class="po-title">分组显隐</div>
      <label v-for="s in sections" :key="s.id" class="po-switch">
        <input type="checkbox" :checked="isGroupOn(s.id)" @change="toggleGroup(s.id, $event.target.checked)">
        <i :style="{ background: s.color }"></i>
        <span>{{ s.name }}</span>
        <b>{{ s.count }}{{ s.unit }}</b>
      </label>
    </div>

    <!-- 全局显示 -->
    <div class="po-sec">
      <div class="po-title">全局显示</div>
      <label class="po-switch"><input type="checkbox" :checked="showGrid" @change="setGrid($event.target.checked)"><span>显示网格地面</span></label>
      <button class="po-btn" @click="restoreWallTextures">一键恢复所有墙体原始贴图</button>
    </div>

    <!-- 光照与背景 -->
    <div class="po-sec">
      <div class="po-title">光照与背景</div>
      <label class="po-slide">半球光强度
        <input type="range" min="0" max="3" step="0.05" v-model.number="light.hemi">
        <b>{{ light.hemi }}x</b>
      </label>
      <label class="po-slide">主光强度
        <input type="range" min="0" max="4" step="0.05" v-model.number="light.key">
        <b>{{ light.key }}x</b>
      </label>
      <label class="po-slide">补光强度
        <input type="range" min="0" max="2" step="0.05" v-model.number="light.fill">
        <b>{{ light.fill }}x</b>
      </label>
      <label class="po-slide">主光方向
        <span class="po-dir">
          X <input type="number" step="1" v-model.number="light.dirX">
          Y <input type="number" step="1" v-model.number="light.dirY">
          Z <input type="number" step="1" v-model.number="light.dirZ">
        </span>
      </label>
      <label class="po-color">背景色
        <input type="color" v-model="light.background">
        <b>{{ light.background }}</b>
      </label>
      <button class="po-btn" @click="resetLight">恢复默认光照</button>
    </div>

    <div class="po-tip">提示：尺寸修改后按「视角按钮」可重新调整相机；自动旋转开启时切换视角会先暂停旋转。</div>
  </div>
</template>

<script>
import { ref, watch, nextTick } from 'vue'
import { getCtx } from '../../lib/modelCtx'
import { editorState, requestSizeEdit, requestTextureApply } from '../../lib/editorState'

export default {
  name: 'PanelOverall',
  props: {
    info: { type: Object, required: true }
  },
  setup() {
    const ctx = getCtx()
    // 尺寸轴映射：21 默认 长 Z / 宽 X；22 在 catalog meta.axis 声明为 长 X / 宽 Z。
    const axis = (ctx.meta && ctx.meta.axis) || { length: 'z', width: 'x', height: 'y' }
    const sections = ctx.catalog.sections
    const showGrid = ref(editorState.display.grid)
    const light = editorState.lighting // 直接改响应式状态，Viewer3D watch 应用

    const LIGHT_DEFAULT = { hemi: 0.55, key: 1.7, fill: 0.4, dirX: 6, dirY: 9, dirZ: 5, background: '#e9f0f8' }
    function resetLight() {
      Object.assign(light, LIGHT_DEFAULT)
    }

    // 模型尺寸草稿（整体尺寸变化后同步）
    const draft = ref({ ...editorState.sizes.model })
    watch(
      () => ({ ...editorState.sizes.model }),
      (v) => { draft.value = { ...v } },
      { deep: true }
    )

    function isGroupOn(id) {
      return editorState.display.groups[id] !== false
    }
    /** 内部净尺寸展示：按模型轴映射 长×宽×高（米） */
    function fmtInner(o) {
      if (!o) return ''
      const L = o[axis.length]
      const W = o[axis.width]
      const H = o[axis.height]
      return `长 ${L} m × 宽 ${W} m × 高 ${H} m`
    }
    function toggleGroup(id, on) {
      editorState.display.groups[id] = on
    }
    function setGrid(on) {
      editorState.display.grid = on
      showGrid.value = on
    }
    /** 一键恢复所有墙体原始贴图（all=true + texId='original'） */
    function restoreWallTextures() {
      requestTextureApply('', 'original', 1, true)
    }
    function applyModel() {
      const d = draft.value
      requestSizeEdit('model', { x: d.x, y: d.y, z: d.z })
    }

    // 尺寸标注点击 → 聚焦对应输入框（长/宽/高）
    const lenRef = ref(null)
    const widRef = ref(null)
    const heiRef = ref(null)
    const FIELD_REFS = { length: lenRef, width: widRef, height: heiRef }
    watch(
      () => editorState.focusField,
      (f) => {
        if (!f) return
        // 等 PanelOverall 完成挂载/渲染后再聚焦输入框
        nextTick(() => {
          const r = FIELD_REFS[f]
          if (r && r.value) {
            r.value.focus()
            r.value.select()
          }
        })
        // 清除，避免重复聚焦
        editorState.focusField = ''
      }
    )

    return { sections, axis, showGrid, draft, light, resetLight, isGroupOn, fmtInner, toggleGroup, setGrid, applyModel, lenRef, widRef, heiRef, restoreWallTextures }
  }
}
</script>

